def maximal_blocks(i):
    pts=[(r,c) for r in range(len(i)) for c in range(len(i[0])) if i[r][c]==2]
    seen=set(); res=[]
    for p in pts:
        if p in seen: continue
        st=[p]; comp=[]
        while st:
            q=st.pop()
            if q in seen: continue
            seen.add(q); comp.append(q)
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    qq=(q[0]+dr,q[1]+dc)
                    if qq in set(pts) and qq not in seen: st.append(qq)
        # keep only pure 2x2 squares (4 cells, exact) that contain all comp cells
        ok=None
        for r0 in range(min(p[0] for p in comp), max(p[0] for p in comp)+1):
            for c0 in range(min(p[1] for p in comp), max(p[1] for p in comp)+1):
                sq={(r0+i,c0+j) for i in(0,1) for j in(0,1)}
                if sq==set(comp) and len(comp)==4:
                    ok=(r0,c0); break
            if ok: break
        res.append(ok)
    return res
